var nullable = (schema) => ({ anyOf: [schema, { type: "null" }] });
var str = { type: "string" };
var strOrNull = { type: ["string", "null"] };
var strList = { type: "array", items: str };
var obj = (properties) => ({
  type: "object",
  properties,
  required: Object.keys(properties),
  additionalProperties: false
});
var pairText = obj({ text: str, translation: str });
var GERMAN_VERB = obj({
  separable: { type: "boolean" },
  auxiliary: { type: "string", enum: ["haben", "sein"] },
  reflexive: { type: "string", enum: ["none", "accusative", "dative"] },
  irregular: { type: "boolean" },
  partizip2: str,
  government: strOrNull,
  praesens: strList,
  praeteritum: strList,
  konjunktiv1: strList,
  konjunktiv2: strList,
  imperativ: obj({ du: str, ihr: str, Sie: str })
});
var CONJUGATION = obj({
  auxiliary: strOrNull,
  irregular: { type: "boolean" },
  separable: { type: "boolean" },
  reflexive: { type: "boolean" },
  participle: str,
  government: strOrNull,
  tenses: { type: "array", items: obj({ name: str, forms: { type: "array", items: obj({ person: str, form: str }) } }) }
});
function nounSchema(target) {
  if (target === "de") {
    return obj({ article: { type: "string", enum: [...ARTICLE_VALUES] }, plural: strOrNull, genitive: strOrNull, plural_only: { type: "boolean" } });
  }
  const articles = Object.keys(ARTICLES[target] ?? {});
  return obj({
    article: articles.length ? nullable({ type: "string", enum: articles }) : { type: "null" },
    gender: articles.length ? nullable({ type: "string", enum: [...GENDER_VALUES] }) : { type: "null" },
    plural: strOrNull,
    plural_only: { type: "boolean" }
  });
}
function outputSchema(target) {
  return obj({
    status: { type: "string", enum: [...AI_STATUS] },
    suggestion: strOrNull,
    input_note: strOrNull,
    lemma: str,
    pos: { type: "string", enum: [...POS_VALUES] },
    cefr: { type: "string", enum: [...CEFR_VALUES] },
    ipa: strOrNull,
    meanings: {
      type: "array",
      items: obj({
        translation: str,
        note: strOrNull,
        examples: { type: "array", items: obj({ level: { type: "string", enum: [...EXAMPLE_LEVELS] }, text: str, translation: str }) }
      })
    },
    noun: nullable(nounSchema(target)),
    verb: target === "de" ? nullable(GERMAN_VERB) : { type: "null" },
    conjugation: target === "de" ? { type: "null" } : nullable(CONJUGATION),
    adjective: nullable(obj({ comparative: strOrNull, superlative: strOrNull })),
    synonyms: strList,
    antonyms: strList,
    collocations: { type: "array", items: pairText },
    learner_note: strOrNull,
    register: nullable({ type: "string", enum: [...REGISTER_VALUES] }),
    frequency: nullable({ type: "integer", enum: [1, 2, 3] }),
    literal: strOrNull,
    alternatives: strList,
    reply: nullable(pairText)
  });
}
var AI_OUTPUT_SCHEMA = outputSchema("de");

// supabase/functions/_shared/story.ts
var LEVELS = ["A1", "A2", "B1", "B2", "C1"];
var PERSIAN2 = /[؀-ۿ]/;
var LATIN = /\p{Script=Latin}/u;
var STORY_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["title_de", "title_fa", "sentences", "used_words"],
  properties: {
    title_de: { type: "string" },
    title_fa: { type: "string" },
    sentences: {
      type: "array",
      items: { type: "object", additionalProperties: false, required: ["de", "fa"], properties: { de: { type: "string" }, fa: { type: "string" } } }
    },
    used_words: { type: "array", items: { type: "string" } }
  }
};
function storySystem(pair) {
  const n = pairNames(pair);
  return `You write short, warm, everyday ${n.target} reading texts for ${n.native}-speaking learners.
Write ONE short story or dialogue (6 to 10 sentences) at the requested CEFR level, set in everyday life (family, work, shopping, friends, travel, appointments). Use as many of the given words as fit naturally — at least half of them — in any grammatical form; you may add other simple words of the level. Each sentence ("de"): natural standard ${n.target} with correct grammar and punctuation, at most 20 words. Give a faithful, natural ${n.native} translation of every sentence ("fa"), written in ${n.nativeRules} In a dialogue, start lines with the speaker's first name and a colon in both languages. "used_words": the given words you actually used, exactly as given. Titles: a short ${n.target} title ("title_de") and its ${n.native} translation ("title_fa"). Nothing violent, sexual or political.`;
}
function validateStory(raw, given, native = "fa") {
  const script = nativeScript(native);
  const nativeOk = (v) => !script || script.test(v);
  const targetOk = (v) => LATIN.test(v) && !(script && script.test(v));
  if (!raw || typeof raw !== "object")
    return null;
  const r = raw;
  const clean = (v, max) => typeof v === "string" ? v.normalize("NFC").replace(/\s+/g, " ").trim().slice(0, max) : "";
  const title_de = clean(r.title_de, 200);
  const title_fa = clean(r.title_fa, 200);
  if (!title_de || !targetOk(title_de) || !title_fa || !nativeOk(title_fa))
    return null;
  const list = Array.isArray(r.sentences) ? r.sentences : [];
  const sentences = [];
  for (const item of list.slice(0, 14)) {
    const s = item ?? {};
    const de = clean(s.de, 300);
    const fa = clean(s.fa, 300);
    if (!de || !fa || !targetOk(de) || !nativeOk(fa))
      return null;
    sentences.push({ de, fa });
  }
  if (sentences.length < 3)
    return null;
  const givenSet = new Set(given.map((w) => w.toLocaleLowerCase("de")));
  const words = (Array.isArray(r.used_words) ? r.used_words : []).map((w) => clean(w, 80)).filter((w) => givenSet.has(w.toLocaleLowerCase("de")));
  return { title_de, title_fa, sentences, words: [...new Set(words)] };
}
async function handleStory(req, env, fetchImpl = fetch, sleep = (ms) => new Promise((r) => setTimeout(r, ms))) {
  const cors = corsHeaders(req, env);
  if (req.method === "OPTIONS")
    return new Response(null, { status: 204, headers: cors });
  try {
    if (req.method !== "POST")
      throw new HttpError(405, "method_not_allowed", "Use POST");
    if (!env.supabaseUrl || !env.serviceRoleKey)
      throw new HttpError(500, "not_configured", "Server is not configured");
    const user = await requireUser(req, env, fetchImpl);
    const body = await readJsonBody(req, 4000);
    const words = (Array.isArray(body.words) ? body.words : []).filter((w) => typeof w === "string").map((w) => w.normalize("NFC").replace(/\s+/g, " ").trim()).filter((w) => w && w.length <= 80 && LATIN.test(w) && !PERSIAN2.test(w)).slice(0, 40);
    if (words.length < 3)
      throw new HttpError(400, "invalid_input", "At least three known words are needed");
    const level = typeof body.level === "string" && LEVELS.includes(body.level) ? body.level : "A2";
    const pair = {
      target: typeof body.targetLanguage === "string" ? body.targetLanguage : "de",
      native: typeof body.nativeLanguage === "string" ? body.nativeLanguage : "fa"
    };
    if (!isSupportedPair(pair))
      throw new HttpError(400, "unsupported_language", "This language pair is not available");
    const db = adminRest(env, fetchImpl);
    await checkAllowance(db, user.id, "story", 3);
    if (!env.aiApiKey || !env.aiModel || !env.aiBaseUrl)
      throw new HttpError(500, "not_configured", "The AI service is not configured");
    const messages = [
      { role: "system", content: storySystem(pair) },
      { role: "user", content: `Level: ${level}
Words: ${JSON.stringify(words)}` }
    ];
    let story = null;
    let usage = { inputTokens: 0, outputTokens: 0 };
    for (let attempt = 0;attempt < 2 && !story; attempt++) {
      const answer = await callStructured(messages, env, { name: "story", schema: STORY_SCHEMA, maxOutputTokens: 3000 }, fetchImpl, sleep);
      usage = { inputTokens: usage.inputTokens + answer.usage.inputTokens, outputTokens: usage.outputTokens + answer.usage.outputTokens };
      try {
        story = validateStory(JSON.parse(answer.text), words, pair.native);
      } catch {
        story = null;
      }
    }
    await db.insert("ai_generation_logs", { user_id: user.id, kind: "story", status: story ? "ok" : "error", model: env.aiModel, input_tokens: usage.inputTokens, output_tokens: usage.outputTokens }).catch(() => {
      return;
    });
    if (!story)
      throw new HttpError(502, "ai_invalid_output", "The story was not usable");
    const id = crypto.randomUUID();
    await db.insert("stories", { id, user_id: user.id, level, title_de: story.title_de, title_fa: story.title_fa, sentences: story.sentences, words: story.words });
    return json({ id, level, ...story }, 200, cors);
  } catch (err) {
    return errorResponse(err, cors);
  }
}

// supabase/functions/story/index.ts
var env = (name) => Deno.env.get(name) || undefined;
Deno.serve((req) => handleStory(req, {
  supabaseUrl: env("SUPABASE_URL") ?? "",
  serviceRoleKey: resolveServiceKey(env),
  allowedOrigins: env("ALLOWED_ORIGINS") ?? "",
  ...resolveAiSettings(env)
}));
